CREATE TABLE Clientes (Id INT IDENTITY PRIMARY KEY, [Nombre] NVARCHAR(200) NOT NULL, [Apellido] NVARCHAR(200) NOT NULL, [Telefono] NVARCHAR(200) NOT NULL, [Correo] NVARCHAR(200) NOT NULL, [Activo] BIT NOT NULL);
CREATE TABLE Empleados (Id INT IDENTITY PRIMARY KEY, [Nombre] NVARCHAR(200) NOT NULL, [Apellido] NVARCHAR(200) NOT NULL, [Telefono] NVARCHAR(200) NOT NULL, [Correo] NVARCHAR(200) NOT NULL, [Especialidad] NVARCHAR(200) NOT NULL, [Activo] BIT NOT NULL);
CREATE TABLE Servicios (Id INT IDENTITY PRIMARY KEY, [Nombre] NVARCHAR(200) NOT NULL, [Descripcion] NVARCHAR(200) NOT NULL, [DuracionMin] INT NOT NULL CHECK ([DuracionMin] > 0), [Precio] DECIMAL(10,2) NOT NULL CHECK ([Precio] >= 0), [Activo] BIT NOT NULL);
CREATE TABLE Usuarios (Id INT IDENTITY PRIMARY KEY, [Nombre] NVARCHAR(200) NOT NULL, [Usuario] NVARCHAR(200) NOT NULL UNIQUE, [Clave] NVARCHAR(300) NOT NULL, [Rol] NVARCHAR(200) NOT NULL, [Activo] BIT NOT NULL);
CREATE TABLE Productos (Id INT IDENTITY PRIMARY KEY, [Nombre] NVARCHAR(200) NOT NULL, [Precio] DECIMAL(10,2) NOT NULL CHECK ([Precio] >= 0), [StockMinimo] INT NOT NULL CHECK ([StockMinimo] >= 0), [Activo] BIT NOT NULL);
CREATE TABLE Horarios (Id INT IDENTITY PRIMARY KEY, [Empleado] INT NOT NULL REFERENCES Empleados(Id), [Dia] NVARCHAR(200) NOT NULL, [Entrada] TIME NOT NULL, [Salida] TIME NOT NULL, CHECK (Entrada < Salida), UNIQUE(Empleado,Dia,Entrada));
CREATE TABLE Citas (Id INT IDENTITY PRIMARY KEY, [Cliente] INT NOT NULL REFERENCES Clientes(Id), [Empleado] INT NOT NULL REFERENCES Empleados(Id), [Fecha] DATE NOT NULL, [Hora] TIME NOT NULL, [Estado] NVARCHAR(200) NOT NULL, [Observaciones] NVARCHAR(200) NOT NULL, CHECK (Estado IN ('Confirmada','Pendiente','Realizada','Cancelada')));
CREATE TABLE DetalleCita (Id INT IDENTITY PRIMARY KEY, [Cita] INT NOT NULL REFERENCES Citas(Id), [Servicio] INT NOT NULL REFERENCES Servicios(Id), [Cantidad] INT NOT NULL CHECK ([Cantidad] > 0), [PrecioUnitario] DECIMAL(10,2) NOT NULL CHECK ([PrecioUnitario] >= 0));
CREATE TABLE Recordatorios (Id INT IDENTITY PRIMARY KEY, [Cita] INT NOT NULL REFERENCES Citas(Id), [Tipo] NVARCHAR(200) NOT NULL, [Mensaje] NVARCHAR(200) NOT NULL, [FechaEnvio] DATETIME2 NOT NULL, [Enviado] BIT NOT NULL);
CREATE TABLE Movimientos (Id INT IDENTITY PRIMARY KEY, [Producto] INT NOT NULL REFERENCES Productos(Id), [Tipo] NVARCHAR(200) NOT NULL CHECK (Tipo IN ('Entrada','Salida')), [Cantidad] INT NOT NULL CHECK ([Cantidad] > 0), [Fecha] DATE NOT NULL);
CREATE TABLE Facturas (Id INT IDENTITY PRIMARY KEY, [Cita] INT NOT NULL REFERENCES Citas(Id), [Fecha] DATE NOT NULL, UNIQUE(Cita));
CREATE TABLE DetalleFactura (Id INT IDENTITY PRIMARY KEY, [Factura] INT NOT NULL REFERENCES Facturas(Id), [Servicio] INT NOT NULL REFERENCES Servicios(Id), [Cantidad] INT NOT NULL CHECK ([Cantidad] > 0), [PrecioUnitario] DECIMAL(10,2) NOT NULL CHECK ([PrecioUnitario] >= 0));
CREATE TABLE MetodosPago (Id INT IDENTITY PRIMARY KEY, [Nombre] NVARCHAR(200) NOT NULL UNIQUE);
CREATE TABLE Pagos (Id INT IDENTITY PRIMARY KEY, [Factura] INT NOT NULL REFERENCES Facturas(Id), [Metodo] INT NOT NULL REFERENCES MetodosPago(Id), [Monto] DECIMAL(10,2) NOT NULL CHECK ([Monto] > 0), [Fecha] DATE NOT NULL);
