CREATE UNIQUE INDEX UX_DetalleCita ON DetalleCita(Cita,Servicio);
CREATE UNIQUE INDEX UX_DetalleFactura ON DetalleFactura(Factura,Servicio);
CREATE UNIQUE INDEX UX_CitaHorario ON Citas(Empleado,Fecha,Hora) WHERE Estado <> N'Cancelada';
